package com.secman.controller

import com.secman.service.*
import com.secman.domain.*
import com.secman.dto.mcp.*
import io.micronaut.http.HttpResponse
import io.micronaut.http.HttpStatus
import io.micronaut.http.annotation.*
import io.micronaut.security.annotation.Secured
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Inject
import jakarta.validation.Valid
import org.slf4j.LoggerFactory
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/**
 * Administrative controller for MCP management operations.
 * Requires admin authentication via JWT.
 */
@Controller("/api/mcp/admin")
@Secured("ADMIN")
open class McpAdminController(
    @Inject private val authService: McpAuthenticationService,
    @Inject private val sessionService: McpSessionService,
    @Inject private val auditService: McpAuditService,
    @Inject private val toolPermissionService: McpToolPermissionService,
    @Inject private val userService: UserService,
    @Inject private val apiKeyRepository: com.secman.repository.McpApiKeyRepository,
    @Inject private val userRepository: com.secman.repository.UserRepository
) {
    private val logger = LoggerFactory.getLogger(McpAdminController::class.java)

    @io.micronaut.serde.annotation.Serdeable
    data class DelegateUser(val id: Long?, val username: String, val email: String)

    /** Minimal, bounded directory lookup for the admin key-creation picker. */
    @Get("/delegate-users{?query}")
    fun delegateUsers(@QueryValue(defaultValue = "") query: String): HttpResponse<*> {
        if (query.length > 255) return HttpResponse.badRequest(mapOf("message" to "Search is too long"))
        return HttpResponse.ok(userRepository.searchAssessmentParticipants(
            query.trim(), io.micronaut.data.model.Pageable.from(0, 50)
        ).map { DelegateUser(it.id, it.username, it.email) })
    }

    // ===== API KEY MANAGEMENT =====

    /**
     * Create a new MCP API key.
     *
     * Supports user delegation:
     * - delegationEnabled: Enable delegation for this key
     * - allowedDelegationDomains: Required if delegation enabled (comma-separated, e.g. "@company.com")
     */
    @Post("/api-keys")
    open suspend fun createApiKey(
        @Valid @Body request: McpApiKeyCreateRequest,
        authentication: Authentication?
    ): HttpResponse<McpApiKeyCreateResponse> {
        return try {
            val userId = getUserIdFromAuth(authentication)
            if (userId == null) {
                return HttpResponse.status<McpApiKeyCreateResponse>(HttpStatus.UNAUTHORIZED)
                    .body(McpApiKeyCreateResponse(error = McpErrorResponse("AUTH_FAILED", "Invalid authentication")))
            }

            // Validate request
            val validationError = validateApiKeyRequest(request)
            if (validationError != null) {
                logger.debug("Request validation failed: {}", validationError)
                return HttpResponse.badRequest(
                    McpApiKeyCreateResponse(error = McpErrorResponse("INVALID_REQUEST", validationError))
                )
            }

            if (request.allowedDelegateUserIds.size > 100 || request.allowedDelegateUserIds.any { it <= 0 }) {
                return HttpResponse.badRequest(McpApiKeyCreateResponse(
                    error = McpErrorResponse("INVALID_REQUEST", "Specify at most 100 positive delegate user IDs")))
            }

            // Validate delegation configuration
            val delegationValidationError = validateDelegationConfig(request.delegationEnabled, request.allowedDelegationDomains)
            if (delegationValidationError != null) {
                logger.debug("Delegation validation failed: {}", delegationValidationError)
                return HttpResponse.badRequest(
                    McpApiKeyCreateResponse(error = McpErrorResponse("INVALID_DELEGATION_CONFIG", delegationValidationError))
                )
            }

            // Check for duplicate names
